problem:
Let $A$ and $B$ be two points on the parabola $y = x^2,$ such that when the tangents at $A$ and $B$ drawn, they are perpendicular.  Then for any such pair of tangents, the $y$-coordinate of their point of intersection $P$ is always the same.  Find this $y$-coordinate.

[asy]
unitsize(1.5 cm);

real parab (real x) {
  return(x^2);
}

pair A, B, P;
real a, b;

a = 1;
b = (-1/4)/a;
A = (a,a^2);
B = (b,b^2);
P = extension(A, A + (1,2*a), B, B + (1,2*b));

draw(graph(parab,-1.5,1.5));
draw(interp(A,P,-0.8)--interp(A,P,1.2));
draw(interp(B,P,-1)--interp(B,P,1.5));
draw(rightanglemark(A,P,B,5));

label("$P$", P, S);

dot("$A$", A, SE);
dot("$B$", B, S);
[/asy]

Part of the graph of $f(x) = ax^3 + bx^2 + cx + d$ is shown. What is $b$?

[asy]
unitsize(1.5 cm);

real func(real x) {
  return((x + 1)*(x - 1)*(x - 2));
}

draw(graph(func,-1.1,1.5));
draw((-1.5,0)--(1.5,0),Arrows(6));
draw((0,-1)--(0,2.5),Arrows(6));

label("$x$", (1.5,0), E);
label("$f(x)$", (0,2.5), N);

dot("$(-1,0)$", (-1,0), SE, fontsize(10));
dot("$(1,0)$", (1,0), SW, fontsize(10));
dot("$(0,2)$", (0,2), NE, fontsize(10));
[/asy]
